"use server"
const backend_url = "http://localhost:3001";

//create post
export default async function Bccrtpost(formData: any) {
  try {
    const senddata = await fetch(`${backend_url}/create-post`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(formData),
    });
    const data = await senddata.json();

    return { success: true, data };
  } catch (error) {
    console.error(error);
    return { success: false, error };
  }
}

//get post
export async function Bcgetpost(username: any) {
  const url = `${backend_url}/get-post?username=${username}`;
  try {
    const getpost = await fetch(url);
  
    const data = await getpost.json();
    return { success: true, data };
  } catch (error) {
    console.error(error);
    return { success: false, error };
  }
}
